__NUXT_JSONP__("/tw/hollywood", (function(a,b){return {data:[{details:{slug:a,pageTitle:"Hollywood院區 | Mentor Language Institute",pageDescription:b,title:"Hollywood院區",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fhollywood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FUzMNGL0_SzU",subtitle:[b,"我們Hollywood的學生大多對於舞蹈、音樂、演藝、電影、瑜珈等方面的環境有興趣。有名的Musician Institute就在我們學院的對街。","那裏有許多舞蹈工作室像是:"],lists:["Musician Institute","Edge Performing Arts","Millennium Dance Complex","Debbie Raynolds","MovementLifestyle","Los Angeles Film School","NY Film Academy"],other_desc:["Hollywood院區對於依賴公共交通工具的國際學生是一個方便完美的地方(the Hollywood 及 Highland 站牌距離院區只有兩分鐘路程)。","如果您喜歡小班制且喜歡娛樂\u002F電影\u002F音樂圈的環境，請加入我們MLI的Hollywood學院!"],albums:[{title:"院區",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-2.jpg"]},{title:"教室",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-2.jpg"]}],location:{title:"地點",link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3303.7636753752786!2d-118.3467233847837!3d34.1011940805926!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bf239f1c4a45%3A0x6953aa45bd461a42!2sMentor%20Language%20Institute%20-%20Hollywood!5e0!3m2!1sen!2sph!4v1576725075448!5m2!1sen!2sph"},video:[{title:"1. 如何經好萊塢高地火車站前往MLI好萊塢校區",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FrP3AV1P3duU"},{title:"2. 如何駕車前往MLI Hollywood Campus",addspace:"\u003Cbr\u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FJO2iqyI9Dfc"}],accommodation:{title:"住宿",description:["我們提供寄宿家庭或宿舍兩個住宿選擇","＜宿舍＞\u003Cbr\u002F\u003E","我們的宿舍都位於離學校很近的方便地區。"],information:[{yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F27o22DzbFp0",desc:["＜寄宿家庭＞ \u003Cbr\u002F\u003E","寄宿家庭是增進說英語及學習美國文化的最佳機會。","\u003Ca href=\"\u002Ftw\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E 更多關於住宿資訊\u003C\u002Fa\u003E"]}]},courses:{title:"課程總覽",lists:["ESL 課程","TOEFL®(托福)","口說對話課程","TOEIC®(多益)課程"]},message:{title:"來自Hollywood院區的話",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fjulie.jpg",position:"來自校長的話",description:["MLI 的Hollywood院區位於繁忙的Hollywood市中心，距離 the Hollywood\u002FHighland車站只有兩分鐘路程。The Dolby Theater, Chinese Theater, 以及 Walk of Fame就在我們院區的旁邊，提供很多讓生活更有趣的機會。"]},dir:"\u002Fhollywood",path:"\u002Fhollywood\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:29.576Z",updatedAt:"2025-05-26T12:06:27.781Z"},lang:a}],fetch:{},mutations:void 0}}("tw","Hollywood院區以娛樂圈重心為名。奧斯卡頒獎典禮，以及許多電影首映都是在Dolby劇院舉辦，距離我們學院只有兩分鐘路程。您將有機會可以看到電影明星在Dolby劇院前踏出他們豪華轎車的時候。")));